// src/TimeClock.Domain/VarianceExamples.cs
public interface ISource<out T> { T Get(); }

ISource<Employee> employeeSource = new SingleSource<Employee>(someEmployee);
ISource<object> widened = employeeSource;   // legal: covariance
object value = widened.Get();               // still just reads an Employee, typed as object

public interface ISink<in T> { void Add(T item); }

ISink<object> objectSink = new CountingSink<object>();
ISink<Employee> narrowed = objectSink;      // legal: contravariance
narrowed.Add(someEmployee);                 // objectSink.Add ultimately runs, accepting the Employee fine
